// icon('home') -> <svg ...>
function icon($name, $class = '')
{
    $paths = icon_paths();
    if (!isset($paths[$name])) {
        $name = 'chats';
    }
    return '<svg class="icon ' . $class . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $paths[$name] . '</svg>';
}

function icon_names()
{
    return array_keys(icon_paths());
}
